def solve(gas,cost):
    if not gas: return -1
    total=tank=start=0
    for i,(g,c) in enumerate(zip(gas,cost)):
        total+=g-c
        tank+=g-c
        if tank<0:
            start=i+1
            tank=0
    return -1 if total<0 else start%len(gas)
